105	// --- MCP Server ---
106	
107	// Sourced from package.json so the version reported over MCP cannot drift from
108	// the version actually published.
109	const SERVER_VERSION: string = (() => {
110	  for (const rel of ["../package.json", "../../package.json"]) {
111	    try {
112	      const url = new URL(rel, import.meta.url);
113	      if (existsSync(url)) {
114	        const pkg = JSON.parse(readFileSync(url, "utf8")) as { version?: string };
115	        if (pkg.version) return pkg.version;
116	      }
117	    } catch {
118	      /* fall through to the next candidate */
119	    }
120	  }
121	  return "0.0.0";
122	})();
