179	const isDirectExecution = ((): boolean => {
180	  if (!process.argv[1]) return false;
181	  // Compare real paths, not lexical ones. Components reach this server through
182	  // a symlinked mcp-server/ directory, so the invoked path and import.meta.url
183	  // legitimately differ; a lexical comparison made the server exit 0 without
184	  // ever starting, which reads as "crashed silently" to every caller.
185	  const realOrSelf = (candidate: string): string => {
186	    try {
187	      return realpathSync(candidate);
188	    } catch {
189	      return resolve(candidate);
190	    }
191	  };
192	  return realOrSelf(process.argv[1]) === realOrSelf(fileURLToPath(import.meta.url));
193	})();
194	
195	if (isDirectExecution) {
196	  main().catch((err) => {
197	    console.error("Fatal:", err);
198	    process.exit(1);
199	  });
200	}
