  1	import type { Host, Registry, RouteRecommendation } from "./platform_types.js";
  2	import { checkHostModelHealth, modelNamesForHost } from "./routing_endpoint_runtime.js";
  3	import { TIER_IDS } from "./runtime_constants.js";
  4	import {
  5	  failureKey,
  6	  type SupervisorRoute,
  7	  type WatchdogRouteCandidates,
  8	} from "./supervisor_runtime.js";
  9	
 10	const TASK_KEYWORDS: Record<string, string[]> = {
 11	  [TIER_IDS.local]: [
 12	    "implement",
 13	    "code",
 14	    "edit",
 15	    "fix",
 16	    "build",
 17	    "test",
 18	    "review",
 19	    "deploy",
 20	    "release",
 21	    "fast",
 22	    "quick",
 23	    "small",
 24	    "obvious",
 25	    "plan",
 26	    "planner",
 27	    "planning",
 28	    "orchestrate",
 29	    "orchestrator",
 30	    "architecture",
 31	  ],
 32	  [TIER_IDS.tailscaleOllama]: [
 33	    "subagent",
 34	    "delegate",
 35	    "delegated",
 36	    "parallel",
 37	    "overflow",
 38	    "offload",
