 64	export function cloudRoutingAllowed(registry: Registry): boolean {
 65	  const envOptIn = (process.env.XX_STACK_ALLOW_CLOUD ?? "").toLowerCase();
 66	  if (envOptIn === "1" || envOptIn === "true") {
 67	    return true;
 68	  }
 69	  return registry.selectionPolicy.cloudEscalation?.optIn === true;
 70	}
 71	
 72	function routableTierIds(registry: Registry): string[] {
 73	  const allowCloud = cloudRoutingAllowed(registry);
 74	  return registry.selectionPolicy.defaultOrder.filter(
 75	    (tierId) => allowCloud || tierId !== TIER_IDS.cloud
 76	  );
 77	}
 78	
 79	export async function buildWatchdogRouteCandidates(
 80	  registry: Registry,
 81	  description: string,
 82	  preferredHost: string | null,
 83	  preferredModel: string | null,
 84	  maxFallbacks: number,
 85	  banned: Set<string>
 86	): Promise<WatchdogRouteCandidates> {
 87	  const baseRoute = routeTask(description, registry);
 88	  const primaryLookup = preferredHost || baseRoute.recommendedHost;
 89	  const selectedPrimary = primaryLookup ? findHostById(registry, primaryLookup) : null;
 90	
 91	  if (!selectedPrimary) {
 92	    return {
 93	      primary: null,
 94	      healthyPrimary: false,
 95	      candidates: [],
 96	      health: [{ status: "unavailable", reason: "No reachable primary host" }],
 97	    };
 98	  }
 99	
100	  const primaryModel =
101	    preferredModel ??
102	    baseRoute.recommendedModel ??
103	    chooseModelForTask(selectedPrimary.host, description);
104	  const primaryHealth = await checkHostModelHealth(selectedPrimary.host, primaryModel);
105	  const primaryRoute: SupervisorRoute = {
106	    tier: selectedPrimary.tierId,
107	    host: selectedPrimary.host.id,
108	    endpoint: selectedPrimary.host.endpoint,
109	    model: primaryModel,
110	  };
111	
112	  const allCandidates = routableTierIds(registry)
113	    .flatMap((tierId) => {
114	      const tier = registry.tiers.find((candidate) => candidate.id === tierId);
115	      return (tier?.hosts ?? []).map((host) => ({ tierId, host }));
116	    })
117	    .filter(({ host }) => host.enabled !== false && host.reachable !== false)
118	    .filter(({ host }) => host.id !== selectedPrimary.host.id)
119	    .sort((left, right) => hostCapacityScore(right.host) - hostCapacityScore(left.host));
120	
121	  // Probe up to maxFallbacks * 2 candidates in parallel so we have healthy spares
122	  const probeCount = Math.min(allCandidates.length, maxFallbacks * 2);
123	  const probeResults = await Promise.all(
124	    allCandidates.slice(0, probeCount).map(async (candidate) => {
125	      const candidateModel = chooseModelForTask(candidate.host, description);
126	      const key = failureKey(candidate.host.id, candidateModel);
127	      if (banned.has(key)) {
128	        return {
129	          candidate,
130	          candidateModel,
131	          candidateHealth: {
132	            hostHealthy: false,
133	            modelAvailable: false,
134	            reason: "circuit breaker active",
135	          } as const,
136	          isBanned: true,
137	        };
138	      }
139	      const candidateHealth = await checkHostModelHealth(candidate.host, candidateModel);
140	      return { candidate, candidateModel, candidateHealth, isBanned: false };
141	    })
142	  );
143	
144	  const candidates: SupervisorRoute[] = [];
145	  const health: Array<Record<string, unknown>> = [
146	    {
147	      tier: selectedPrimary.tierId,
148	      host: selectedPrimary.host.id,
149	      endpoint: selectedPrimary.host.endpoint,
150	      model: primaryModel,
151	      health: primaryHealth,
152	      kind: "primary",
153	    },
154	  ];
155	
156	  for (const probe of probeResults) {
157	    health.push({
158	      tier: probe.candidate.tierId,
159	      host: probe.candidate.host.id,
160	      endpoint: probe.candidate.host.endpoint,
161	      model: probe.candidateModel,
162	      health: probe.candidateHealth,
163	      kind: "fallback",
164	    });
165	
166	    if (
167	      candidates.length < maxFallbacks &&
168	      !probe.isBanned &&
169	      probe.candidateHealth.hostHealthy &&
170	      probe.candidateHealth.modelAvailable
171	    ) {
172	      candidates.push({
173	        tier: probe.candidate.tierId,
174	        host: probe.candidate.host.id,
175	        endpoint: probe.candidate.host.endpoint,
176	        model: probe.candidateModel,
177	      });
178	    }
179	  }
180	
181	  return {
182	    primary: primaryRoute,
183	    healthyPrimary: primaryHealth.hostHealthy && primaryHealth.modelAvailable,
184	    candidates,
185	    health,
186	  };
187	}
188	
189	function modelEntries(host: Host): Array<{
190	  name: string;
191	  roles: string[];
192	  sizeGb: number | null;
193	  format: string | null;
194	  quantization: string | null;
195	  weightBits: number | null;
196	  kernelFamily: string | null;
197	  contextWindow: number | null;
198	  estimatedVramGb: number | null;
199	  supportsToolUse: boolean | null;
200	  toolCallReliability: "unknown" | "low" | "validated";
201	  jsonModeReliability: "unknown" | "low" | "validated";
202	}> {
203	  return (host.models ?? [])
204	    .map((model) => {
205	      if (typeof model === "string") {
206	        return {
207	          name: model,
208	          roles: [],
209	          sizeGb: null,
210	          format: null,
211	          quantization: null,
212	          weightBits: null,
213	          kernelFamily: null,
214	          contextWindow: null,
215	          estimatedVramGb: null,
216	          supportsToolUse: null,
217	          toolCallReliability: "unknown" as const,
218	          jsonModeReliability: "unknown" as const,
219	        };
220	      }
221	      const sizeBytes = typeof model?.size === "number" ? model.size : null;
222	      const inferredWeightBits =
223	        typeof model?.weightBits === "number"
224	          ? model.weightBits
225	          : model?.quantization?.toLowerCase().includes("q1") ||
226	              model?.quantization?.toLowerCase().includes("tq1")
227	            ? 1
228	            : null;
229	      const toolCallReliability: "unknown" | "low" | "validated" =
230	        model?.toolCallReliability === "low" || model?.toolCallReliability === "validated"
231	          ? model.toolCallReliability
232	          : "unknown";
233	      const jsonModeReliability: "unknown" | "low" | "validated" =
234	        model?.jsonModeReliability === "low" || model?.jsonModeReliability === "validated"
235	          ? model.jsonModeReliability
236	          : "unknown";
237	      return {
238	        name: model?.name ?? "",
239	        roles: Array.isArray(model?.roles) ? model.roles : [],
240	        sizeGb: sizeBytes ? Math.round((sizeBytes / 1073741824) * 10) / 10 : null,
241	        format: typeof model?.format === "string" ? model.format : null,
242	        quantization: typeof model?.quantization === "string" ? model.quantization : null,
243	        weightBits: inferredWeightBits,
244	        kernelFamily: typeof model?.kernelFamily === "string" ? model.kernelFamily : null,
245	        contextWindow: typeof model?.contextWindow === "number" ? model.contextWindow : null,
246	        estimatedVramGb: typeof model?.estimatedVramGb === "number" ? model.estimatedVramGb : null,
247	        supportsToolUse: typeof model?.supportsToolUse === "boolean" ? model.supportsToolUse : null,
248	        toolCallReliability,
249	        jsonModeReliability,
250	      };
251	    })
252	    .filter((entry) => Boolean(entry.name));
253	}
254	
255	function maxParallelSlices(host: Host): number {
256	  const configured = Number(host.executionPolicy?.maxParallelSlices ?? 0);
257	  return configured > 0 ? Math.floor(configured) : 1;
258	}
259	
260	export function effectiveParallelCapacity(host: Host): number {
261	  // Parallel request capacity is bounded by slices, not resident-model count:
262	  // one resident model on an OpenAI-compatible server can serve many
263	  // concurrent requests. executionPolicy.maxConcurrentModels is consumed by the
264	  // parallel preflight/smoke tooling, not by routing capacity.
265	  return Math.max(1, maxParallelSlices(host));
266	}
267	
268	export function hostCapacityScore(host: Host): number {
269	  const baseParallel = effectiveParallelCapacity(host);
270	  const detectedVram = Number(host.hardware?.detected?.totalGpuVramGb ?? 0);
271	  const modelCount = modelEntries(host).length;
272	  const primaryBoost = host.primary ? 0.25 : 0;
273	  return baseParallel * 10 + detectedVram * 0.2 + modelCount * 0.5 + primaryBoost;
274	}
275	
276	export function chooseModelForTask(host: Host | null, description: string): string | null {
277	  const entries = host ? modelEntries(host) : [];
278	  if (entries.length === 0) return null;
279	
280	  const desc = description.toLowerCase();
281	  const wantsCode = /implement|code|fix|edit|build|review|test|verify|validation/.test(desc);
282	  const wantsReason = /plan|architect|reason|research|analy|investigate|synthes/.test(desc);
283	  const embeddingTask = /embed|embedding|vector|retrieval/.test(desc);
284	  const strictToolTask = /tool|function\s*call|structured\s*json|strict\s*json|json\s*schema/.test(
285	    desc
286	  );
287	  const longContextTask = /long-context|long context|large-context|synthesis/.test(desc);
288	
289	  let candidates = [...entries];
290	
291	  // Ollama "*:cloud" models proxy inference to Ollama's hosted service and
292	  // would silently bypass the cloud opt-in gate; never auto-select them.
293	  candidates = candidates.filter((entry) => !/:cloud$/i.test(entry.name));
294	  if (candidates.length === 0) return null;
295	
296	  if (!embeddingTask) {
297	    const nonEmbedding = candidates.filter(
298	      (entry) => !/embed|embedding|text-embedding/i.test(entry.name)
299	    );
300	    if (nonEmbedding.length > 0) {
301	      candidates = nonEmbedding;
302	    }
303	  }
304	
305	  if (strictToolTask) {
306	    const validated = candidates.filter(
307	      (entry) =>
308	        entry.supportsToolUse === true &&
309	        entry.toolCallReliability === "validated" &&
310	        entry.jsonModeReliability === "validated"
311	    );
312	    if (validated.length > 0) {
313	      candidates = validated;
314	    }
315	  }
316	
317	  if (longContextTask) {
318	    const turboquant = candidates.filter((entry) =>
319	      (entry.quantization ?? "").toLowerCase().startsWith("tq")
320	    );
321	    if (turboquant.length > 0) {
322	      candidates = turboquant;
323	    }
324	  }
325	
326	  if (wantsCode) {
327	    const coding = candidates.find((entry) =>
328	      entry.roles.some((role) => /build|review|code/.test(role))
329	    );
330	    if (coding) return coding.name;
331	  }
332	
333	  if (wantsReason) {
334	    const reasoning = candidates.find((entry) =>
