  3	import { cloudRoutingAllowed } from "./routing_selection_runtime.js";
  4	import { TIER_IDS } from "./runtime_constants.js";
  5	
  6	export interface ArchitectEditorRoute {
  7	  architect: {
  8	    host: string | null;
  9	    model: string | null;
 10	    reasoning: string;
 11	  };
 12	  editor: {
 13	    host: string | null;
 14	    model: string | null;
 15	    reasoning: string;
 16	  };
 17	  fallback: string | null;
 18	}
 19	
 20	/**
 21	 * Route a task to an architect (reasoning-strong, coder-deep lane) and an
 22	 * editor (low-latency, coder-fast lane) using the existing registry.
 23	 *
 24	 * The architect is selected by routing a reasoning-oriented description
 25	 * through the existing `routeTask` machinery, which matches keywords against
 26	 * tier policies and host roles. The editor is selected similarly with a
 27	 * coding-oriented description.
 28	 *
 29	 * Cloud hosts are excluded unless `XX_STACK_ALLOW_CLOUD=1` or the registry's
 30	 * `selectionPolicy.cloudEscalation.optIn` is set, reusing the existing gate.
 31	 */
 32	export function routeArchitectEditor(
 33	  description: string,
 34	  registry: Registry,
 35	  preferArchitectHost?: string,
 36	  preferEditorHost?: string
 37	): ArchitectEditorRoute {
 38	  const cloudBlocked = !cloudRoutingAllowed(registry);
 39	
 40	  // Route architect using a reasoning-oriented description so the existing
 41	  // keyword/role machinery selects the coder-deep lane.
 42	  const architectDesc = `plan architecture for ${description}`;
 43	  const architectRoute = routeTask(architectDesc, registry);
 44	
 45	  // Route editor using a coding-oriented description so the existing
 46	  // keyword/role machinery selects the coder-fast lane.
 47	  const editorDesc = `implement code for ${description}`;
 48	  const editorRoute = routeTask(editorDesc, registry);
 49	
 50	  // Resolve preferred host overrides if provided
 51	  let architectHost = architectRoute.recommendedHost;
 52	  let architectModel = architectRoute.recommendedModel;
 53	  let architectReasoning = architectRoute.reasoning;
 54	
 55	  if (preferArchitectHost) {
 56	    const resolved = findHostById(registry, preferArchitectHost);
 57	    if (resolved) {
 58	      const model = chooseModelForTask(resolved.host, architectDesc);
 59	      const tierBlocked = cloudBlocked && resolved.tierId === TIER_IDS.cloud;
 60	      architectHost = resolved.host.id;
 61	      architectModel = model;
 62	      architectReasoning = tierBlocked
 63	        ? `Preferred architect host "${preferArchitectHost}" is on cloud tier (excluded); using default route instead. ${architectRoute.reasoning}`
 64	        : `Using preferred architect host "${preferArchitectHost}" (${resolved.tierId}). ${architectRoute.reasoning}`;
 65	      if (tierBlocked) {
 66	        architectHost = architectRoute.recommendedHost;
 67	        architectModel = architectRoute.recommendedModel;
 68	        architectReasoning = architectRoute.reasoning;
 69	      }
 70	    }
 71	  }
 72	
 73	  let editorHost = editorRoute.recommendedHost;
 74	  let editorModel = editorRoute.recommendedModel;
 75	  let editorReasoning = editorRoute.reasoning;
 76	
 77	  if (preferEditorHost) {
 78	    const resolved = findHostById(registry, preferEditorHost);
 79	    if (resolved) {
 80	      const model = chooseModelForTask(resolved.host, editorDesc);
 81	      const tierBlocked = cloudBlocked && resolved.tierId === TIER_IDS.cloud;
 82	      editorHost = resolved.host.id;
 83	      editorModel = model;
 84	      editorReasoning = tierBlocked
 85	        ? `Preferred editor host "${preferEditorHost}" is on cloud tier (excluded); using default route instead. ${editorRoute.reasoning}`
 86	        : `Using preferred editor host "${preferEditorHost}" (${resolved.tierId}). ${editorRoute.reasoning}`;
 87	      if (tierBlocked) {
 88	        editorHost = editorRoute.recommendedHost;
 89	        editorModel = editorRoute.recommendedModel;
 90	        editorReasoning = editorRoute.reasoning;
 91	      }
 92	    }
 93	  }
 94	
 95	  // Build combined reasoning that explains when both collapse to the same lane
 96	  const sameHost = architectHost && architectHost === editorHost;
 97	  const sameModel = architectModel && architectModel === editorModel;
 98	  const collapseReasoning =
 99	    sameHost && sameModel
100	      ? `Both architect and editor resolved to the same host/model (${architectHost}/${architectModel}) because only one lane is available in the current registry.`
101	      : sameHost
102	        ? `Architect and editor resolved to the same host (${architectHost}) but different models (architect: ${architectModel}, editor: ${editorModel}).`
103	        : null;
104	
105	  const fallback = architectRoute.fallback || editorRoute.fallback;
106	
107	  return {
108	    architect: {
109	      host: architectHost,
110	      model: architectModel,
111	      reasoning: collapseReasoning
112	        ? `${collapseReasoning} ${architectReasoning}`
113	        : architectReasoning,
114	    },
115	    editor: {
116	      host: editorHost,
117	      model: editorModel,
118	      reasoning: collapseReasoning
119	        ? `${collapseReasoning} ${editorReasoning}`
120	        : editorReasoning,
121	    },
122	    fallback,
123	  };
124	}

  1	import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
