 18	export function registerRoutingTools(server: McpServer, deps: RoutingToolDeps): void {
 19	  server.tool(
 20	    "route_task",
 21	    "Given a task description, recommend which platform tier, host, and model to use",
 22	    { description: z.string().describe("Description of the task to route") },
 23	    async ({ description }) => {
 24	      const registry = await deps.loadRegistry();
 25	      const result = routeTask(description, registry);
 26	      void logEvent("server", "route_task.result", {
 27	        description: description.slice(0, 200),
