 29	        host: result.recommendedHost,
 30	        model: result.recommendedModel,
 31	        fallback: result.fallback,
 32	        reasoning: result.reasoning,
 33	      });
 34	      return jsonContent(result);
 35	    }
 36	  );
 37	
 38	  server.tool(
 39	    "route_parallel_tasks",
 40	    "Given multiple task descriptions, produce a hardware-aware parallel delegation schedule across local and remote hosts",
 41	    {
 42	      tasks: z
 43	        .array(z.string())
 44	        .min(1)
 45	        .max(128)
 46	        .describe("Task descriptions to schedule in parallel"),
 47	    },
 48	    async ({ tasks }) => {
 49	      const registry = await deps.loadRegistry();
 50	      const schedule = routeParallelTasks(tasks, registry);
 51	      const assignments = schedule.assignments as Array<Record<string, unknown>>;
 52	      void logEvent("server", "route_parallel_tasks.result", {
 53	        taskCount: tasks.length,
 54	        assignedCount: assignments.filter((a) => a["status"] !== "unassigned").length,
 55	        unassignedCount: assignments.filter((a) => a["status"] === "unassigned").length,
 56	        hostUtilization: schedule.hostUtilization,
 57	      });
 58	      return jsonContent(schedule);
 59	    }
 60	  );
 61	
 62	  export function registerArchitectEditorTools(server: McpServer, deps: RoutingToolDeps): void {
 63	  server.tool(
 64	    "route_architect_editor",
 65	    "Route a task to an architect (reasoning-strong, coder-deep lane) and an editor (low-latency, coder-fast lane) using the existing registry. Returns separate host/model/reasoning for each role plus a combined fallback.",
 66	    {
 67	      description: z.string().describe("Description of the task to route"),
 68	      preferArchitectHost: z
 69	        .string()
 70	        .optional()
 71	        .describe("Optional host ID override for the architect lane"),
 72	      preferEditorHost: z
 73	        .string()
 74	        .optional()
 75	        .describe("Optional host ID override for the editor lane"),
 76	    },
