 80	      void logEvent("server", "route_architect_editor.result", {
 81	        description: description.slice(0, 200),
 82	        architectHost: result.architect.host,
 83	        architectModel: result.architect.model,
 84	        editorHost: result.editor.host,
 85	        editorModel: result.editor.model,
 86	        fallback: result.fallback,
 87	      });
 88	      return jsonContent(result);
 89	    }
 90	  );
 91	}
 92	
 93	  server.tool(
 94	    "route_task_with_watchdog",
 95	    "Route a task with host/model liveness checks and automatic failover recommendations",
 96	    {
 97	      description: z.string().describe("Description of the task to route"),
 98	      preferredHost: z
 99	        .string()
100	        .optional()
101	        .describe("Optional host ID override for the primary attempt"),
102	      preferredModel: z
103	        .string()
104	        .optional()
105	        .describe("Optional model override for the primary attempt"),
106	      maxFallbacks: z
