122	        maxFallbacks ?? 3,
123	        new Set<string>()
124	      );
125	
126	      const selectedFailover = candidates.candidates[0] ?? null;
127	      const primaryHealthy = candidates.healthyPrimary;
128	      const status = primaryHealthy ? "healthy" : selectedFailover ? "degraded" : "unavailable";
129	      const primaryHealth =
