131	      const failoverCandidates = candidates.health.filter(
132	        (entry) => (entry as { kind?: string }).kind === "fallback"
133	      );
134	      const reason = primaryHealthy
135	        ? "Primary route passed liveness checks"
136	        : selectedFailover
137	          ? "Primary route failed liveness checks; failover candidate selected"
138	          : "Primary route failed and no healthy failover was found";
139	
140	      void logEvent("server", "route_task_with_watchdog.result", {
141	        description: description.slice(0, 200),
142	        status,
143	        primaryHost: candidates.primary?.host ?? null,
144	        primaryModel: candidates.primary?.model ?? null,
145	        selectedFailoverHost: selectedFailover?.host ?? null,
146	        fallbackCount: candidates.candidates.length,
147	      });
148	
149	      return jsonContent({
150	        status,
151	        reason,
152	        baseRoute,
153	        primary: candidates.primary
154	          ? {
155	              ...candidates.primary,
156	              health: primaryHealth
157	                ? ((primaryHealth as { health?: unknown }).health ?? null)
158	                : null,
159	            }
160	          : null,
161	        selectedFailover,
162	        failoverCandidates,
163	      });
164	    }
165	  );
166	}
