185	const isDirectExecution = ((): boolean => {
186	  if (!process.argv[1]) return false;
187	  // Compare real paths, not lexical ones. Components reach this server through
188	  // a symlinked mcp-server/ directory, so the invoked path and import.meta.url
189	  // legitimately differ; a lexical comparison made the server exit 0 without
190	  // ever starting, which reads as "crashed silently" to every caller.
191	  const realOrSelf = (candidate: string): string => {
